CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(120) PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id VARCHAR(80) PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id VARCHAR(120) PRIMARY KEY, category_id VARCHAR(80) NOT NULL, name VARCHAR(180) NOT NULL, normalized_name VARCHAR(180) NOT NULL, description TEXT NULL, price DECIMAL(10,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT, INDEX idx_products_normalized_name (normalized_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory (product_id VARCHAR(120) PRIMARY KEY, digital_stock INT NOT NULL, physical_stock INT NOT NULL, reorder_point INT NOT NULL, average_sales DECIMAL(10,2) NOT NULL, last_physical_observation_at DATETIME NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_inventory_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT, INDEX idx_inventory_product (product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sales (id VARCHAR(120) PRIMARY KEY, created_at DATETIME NOT NULL, total DECIMAL(10,2) NULL, INDEX idx_sales_created_at (created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sale_items (id VARCHAR(140) PRIMARY KEY, sale_id VARCHAR(120) NOT NULL, product_id VARCHAR(120) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, subtotal DECIMAL(10,2) NOT NULL, CONSTRAINT fk_sale_items_sale FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT, CONSTRAINT fk_sale_items_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS purchases (id VARCHAR(120) PRIMARY KEY, created_at DATETIME NOT NULL, INDEX idx_purchases_created_at (created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS purchase_items (id VARCHAR(140) PRIMARY KEY, purchase_id VARCHAR(120) NOT NULL, product_id VARCHAR(120) NOT NULL, quantity INT NOT NULL, unit_cost DECIMAL(10,2) NULL, CONSTRAINT fk_purchase_items_purchase FOREIGN KEY (purchase_id) REFERENCES purchases(id) ON DELETE RESTRICT, CONSTRAINT fk_purchase_items_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS promotions (id VARCHAR(120) PRIMARY KEY, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, image_url VARCHAR(500) NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS feedback (id VARCHAR(120) PRIMARY KEY, rating TINYINT NOT NULL, comment VARCHAR(500) NOT NULL, created_at DATETIME NOT NULL, INDEX idx_feedback_created_at (created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS edge_observations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, observation_id VARCHAR(180) NOT NULL UNIQUE, zone_id VARCHAR(120) NOT NULL, source_id VARCHAR(120) NOT NULL, observed_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_edge_observation_id (observation_id), INDEX idx_edge_observed_at (observed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS edge_observation_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, edge_observation_id BIGINT UNSIGNED NOT NULL, product_id VARCHAR(120) NOT NULL, quantity INT NOT NULL, CONSTRAINT fk_edge_items_observation FOREIGN KEY (edge_observation_id) REFERENCES edge_observations(id) ON DELETE RESTRICT, CONSTRAINT fk_edge_items_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
